corrected_code:
package handlers

import (
	"net/http"

	"github.com/gorilla/mux"
	"myapp/auth"
	"myapp/services"
)

type InviteController struct {
	InviteService services.WorkspaceInviteService
}

func (c *InviteController) RevokeInvite(w http.ResponseWriter, r *http.Request) {
	vars := mux.Vars(r)
	inviteID := vars["inviteID"]
	caller := auth.CallerFromContext(r.Context())

	err := c.InviteService.RevokeForAdmin(r.Context(), inviteID, caller.UserID, caller.WorkspaceID)
	if err != nil {
		http.Error(w, "Forbidden or invite not found", http.StatusForbidden)
		return
	}

	w.WriteHeader(http.StatusNoContent)
}
